import{_ as r,C as s,o as a,c,a1 as t,E as d}from"./chunks/framework.DceXOx8u.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/architecture"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/architecture"}]]},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),n={name:"guide/architecture.md"};function i(h,e,l,p,u,g){const o=s("Mermaid");return a(),c("div",null,[e[0]||(e[0]=t('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>How <code>@botmesh/core</code> is put together: the package layers, the modules behind the <code>Bot</code> class, the path a message takes in and out, and where the opt-in features (durability, multi-replica coordination, the durable scheduler, tracing) plug in. You don&#39;t need any of this to write a bot. It is for people who extend the core, write a channel or store, or debug what happens between the provider and a handler.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><p>The framework is a pnpm monorepo. Dependencies only point <strong>down</strong>:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Packages</th></tr></thead><tbody><tr><td>Engine</td><td><code>@botmesh/core</code> (its only runtime dependency is <code>pino</code>)</td></tr><tr><td>Shared infrastructure</td><td><code>@botmesh/http</code> (anti-SSRF client), <code>@botmesh/graph-core</code> (Meta Graph helpers), <code>@botmesh/wa-gateway-kit</code> (identity, REST and media shared by Evolution and WPPConnect), <code>@botmesh/server</code> (webhook ingress)</td></tr><tr><td>Channels</td><td><code>@botmesh/baileys</code>, <code>@botmesh/meta</code>, <code>@botmesh/telegram</code>, … (each implements <code>IProvider</code>)</td></tr><tr><td>Stores</td><td><code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code>, … (each implements <code>IStore</code>)</td></tr><tr><td>Plugins / product</td><td><code>@botmesh/ai</code>, <code>nlu</code>, <code>manager</code>, <code>inbox</code>, …</td></tr></tbody></table><p>The core is <strong>transport-agnostic</strong>. It knows nothing about JIDs, QR codes or webhooks: chat, user and message ids are opaque strings it never parses, and the provider resolves identity aliases (LID/PN on WhatsApp, <code>sender_chat</code> on Telegram) <strong>before</strong> it emits an event, so the same person always arrives with the same <code>senderId</code>. Everything channel-specific lives in the channel package.</p><h2 id="inside-the-bot" tabindex="-1">Inside the <code>Bot</code> <a class="header-anchor" href="#inside-the-bot" aria-label="Permalink to &quot;Inside the `Bot`&quot;">​</a></h2><p><code>Bot</code> is a thin <strong>facade</strong>: its methods carry the public documentation and delegate. The engine lives in <code>packages/core/src/core/bot/</code>:</p><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>compose.ts</code></td><td>The constructor body: config defaults, logger, store + namespace, every subsystem, in a fixed order; builds the kernel and the modules below</td></tr><tr><td><code>kernel.ts</code></td><td><code>BotKernel</code>, the shared internals (subsystems + lifecycle state) every module receives, plus tiny shared helpers</td></tr><tr><td><code>logger.ts</code></td><td>Adapts <code>BotConfig.logger</code> (pino, <code>console</code> or any <code>{ debug, info, warn, error }</code>) to the <code>child()</code>-capable logger the modules use</td></tr><tr><td><code>lifecycle.ts</code></td><td><code>start()</code> / <code>stop()</code> as an ordered list of steps, with rollback and drain</td></tr><tr><td><code>inbound.ts</code></td><td>The provider&#39;s event stream → <code>fromMe</code> / echo filter → access gates → dedupe → persistence → <code>groupMode</code> → Dispatcher; calls and provider events (reactions, receipts…)</td></tr><tr><td><code>outbound.ts</code></td><td>Sends and edits through the <code>send</code> hooks, the message ledger, paced replies, typing and <code>ctx.stream()</code></td></tr><tr><td><code>presence.ts</code></td><td>The presence-while-disconnected policy: <code>typing</code> / <code>markRead</code> skipped (debug log + <code>metrics().presenceSkipped</code>) while the transport is not <code>&#39;ready&#39;</code></td></tr><tr><td><code>rateLimitRetry.ts</code></td><td>The short in-place retry of rate-limited <code>ctx</code> replies (<code>BotConfig.rateLimitRetry</code>)</td></tr><tr><td><code>contextFactory.ts</code></td><td>Builds the <code>MessageContext</code> (<code>ctx</code>) of a message, a projected call or a <code>bot.trigger()</code></td></tr><tr><td><code>interactionAck.ts</code></td><td>The single automatic ack of an interaction on a transport with <code>interactionsRequireAck</code> (Discord): before the first send, near <code>respondBy</code> or when routing ends</td></tr><tr><td><code>gates.ts</code></td><td>Access lists and human handoff admission, with their drop counters and logs</td></tr><tr><td><code>handover.ts</code></td><td><code>coordination.handover</code> (only with <code>coordination</code>): records a flow step&#39;s answer in its checkpoint and rebuilds it on the replica that takes the chat</td></tr><tr><td><code>lang.ts</code></td><td><code>ctx.lang</code> resolution and the Dispatcher&#39;s language seams</td></tr><tr><td><code>persistence.ts</code></td><td>Chat / contact / handoff writes, ordered per chat</td></tr><tr><td><code>events.ts</code></td><td>The error and observability event outlet</td></tr><tr><td><code>routes.ts</code></td><td><code>when</code>, <code>conversation</code>, <code>command</code>, <code>onMessage</code>, <code>onType</code>, hooks</td></tr><tr><td><code>pluginHost.ts</code></td><td><code>plug()</code>: a scoped bot whose registrations are undone on unplug</td></tr><tr><td><code>ops.ts</code></td><td><code>trigger</code>, <code>triggerFlow</code>, <code>broadcast</code>, metrics, flow inventory, subject-data collaborators</td></tr></tbody></table><p>Three rules keep this working:</p><ul><li><strong>No <code>#private</code> fields on <code>Bot</code>.</strong> A plugin receives <code>Object.create(bot)</code> as <code>ctx.bot</code>; its methods run with <code>this</code> set to that object, and a <code>#private</code> read through it would throw. The kernel is reached through <code>this</code>, so through the prototype.</li><li><strong>Late-bound seams.</strong> Modules call the bot back through closures (<code>bot.emit</code>, <code>bot.trigger</code>, <code>bot.isHandedOff</code>…) read at call time, so a spy, a subclass override or a plugin-scoped override installed later is honoured.</li><li><strong>Behaviour goes in a module, not in the facade.</strong> Each module stays under 500 lines and opens with a comment saying what it does and what it does not.</li></ul><h2 id="inbound-pipeline" tabindex="-1">Inbound pipeline <a class="header-anchor" href="#inbound-pipeline" aria-label="Permalink to &quot;Inbound pipeline&quot;">​</a></h2><p>Dashed boxes only exist when their feature is configured.</p>',13)),d(o,{code:"flowchart%20TD%0A%20%20%20%20P%5B%22Provider%20event%22%5D%20--%3E%20K%7B%22message%20%2F%20interaction%3F%22%7D%0A%20%20%20%20K%20--%3E%7C%22call%22%7C%20CALL%5B%22Access%20%2B%20handoff%20gates%20%E2%86%92%20'call'%20hooks%20%2B%20event%20%E2%86%92%20CALL%20triggers%20(dispatchEvent)%22%5D%0A%20%20%20%20K%20--%3E%7C%22reaction%2C%20poll%2C%20group%2C%20presence%2C%20status%22%7C%20HE%5B%22before%2Fafter%20hooks%20%2B%20bot%20event%22%5D%0A%20%20%20%20K%20--%3E%7C%22yes%22%7C%20FM%7B%22fromMe%20%2F%20echo%20of%20a%20bot%20send%3F%22%7D%0A%20%20%20%20FM%20--%3E%7C%22yes%22%7C%20X0%5B%22Dropped%20(fromMe%3B%20echo%3A%20dropped.echo)%22%5D%0A%20%20%20%20FM%20--%3E%7C%22no%22%7C%20ACL%7B%22Access%20lists%22%7D%0A%20%20%20%20ACL%20--%3E%7C%22blocked%22%7C%20X1%5B%22Dropped%20(dropped.blocked)%22%5D%0A%20%20%20%20ACL%20--%3E%7C%22allowed%22%7C%20DD%7B%22Dedupe%3A%20chatId%20%2B%20id%22%7D%0A%20%20%20%20DD%20--%3E%7C%22seen%22%7C%20X2%5B%22Dropped%20(dropped.duplicate)%22%5D%0A%20%20%20%20DD%20--%3E%7C%22new%22%7C%20DUR%5B%22Durable%20inbox%3A%20journal%20the%20event%22%5D%0A%20%20%20%20DUR%20--%3E%20PER%5B%22Persist%20chat%2C%20contact%2C%20message%22%5D%0A%20%20%20%20PER%20--%3E%20GM%7B%22groupMode%22%7D%0A%20%20%20%20GM%20--%3E%7C%22ignored%22%7C%20X3%5B%22Stops%20(still%20persisted)%22%5D%0A%20%20%20%20GM%20--%3E%7C%22ok%22%7C%20Q%5B%22Per-chat%20FIFO%20queue%22%5D%0A%20%20%20%20Q%20--%3E%20TURN%5B%22Cross-replica%20chat%20turn%22%5D%0A%20%20%20%20TURN%20--%3E%20D%5B%22Dispatcher%3A%20language%20%E2%86%92%20before('message')%20%E2%86%92%20handoff%20gate%20%E2%86%92%20command%20%E2%86%92%20active%20conversation%20%E2%86%92%20dormant%20resume%20%E2%86%92%20matchers%20%E2%86%92%20catch-all%20%E2%86%92%20after('message')%20%2B%20'message'%20event%22%5D%0A%20%20%20%20style%20DUR%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20TURN%20stroke-dasharray%3A%205%205%0A"}),e[1]||(e[1]=t('<p>The routing stages inside the Dispatcher, in order, are described in <a href="/botmesh/guide/concepts">Core concepts</a>. Two entry points skip parts of this path: <strong>calls</strong> go through the same access and handoff gates and only reach <code>CALL</code> type triggers, and <strong><code>bot.trigger()</code></strong> goes through the access lists, then takes the chat&#39;s queue slot (<code>runExclusive</code>), the handoff gate and language resolution, and starts the conversation directly — no dedupe, persistence, message hooks or matchers.</p><h2 id="outbound-pipeline" tabindex="-1">Outbound pipeline <a class="header-anchor" href="#outbound-pipeline" aria-label="Permalink to &quot;Outbound pipeline&quot;">​</a></h2>',2)),d(o,{code:"flowchart%20TD%0A%20%20%20%20S%5B%22ctx.reply%20%2F%20bot.send%20%2F%20broadcast%22%5D%20--%3E%20PACE%5B%22Pacer%20(ctx%20text%20replies)%3A%20delay%20%2B%20typing%22%5D%0A%20%20%20%20PACE%20--%3E%20IDEM%5B%22Durable%20idempotency%20lookup%22%5D%0A%20%20%20%20IDEM%20--%3E%7C%22already%20sent%22%7C%20PRIOR%5B%22Answered%20from%20the%20outbox%20(no%20hooks%2C%20no%20provider%20call)%22%5D%0A%20%20%20%20IDEM%20--%3E%7C%22new%22%7C%20BS%7B%22before('send')%20hooks%22%7D%0A%20%20%20%20BS%20--%3E%7C%22abort()%22%7C%20SK%5B%22skipped%3A%20true%22%5D%0A%20%20%20%20BS%20--%3E%7C%22proceed%22%7C%20FENCE%5B%22Replica%20fence%3A%20this%20replica%20holds%20the%20chat's%20turn%20%2F%20the%20session%22%5D%0A%20%20%20%20FENCE%20--%3E%20OB%5B%22Durable%20outbox%3A%20journal%20the%20send%22%5D%0A%20%20%20%20OB%20--%3E%20PS%5B%22provider.send%22%5D%0A%20%20%20%20PS%20--%3E%7C%22ok%22%7C%20AS%5B%22metrics%20%E2%86%92%20after('send')%20%E2%86%92%20message%20ledger%20(sent)%22%5D%0A%20%20%20%20PS%20--%3E%7C%22deferred%22%7C%20SW%5B%22Outbox%20sweeper%20delivers%20it%20later%22%5D%0A%20%20%20%20PS%20--%3E%7C%22error%22%7C%20FAIL%5B%22message%20ledger%20(failed)%20%E2%86%92%20error%20to%20the%20caller%22%5D%0A%20%20%20%20style%20PACE%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20IDEM%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20FENCE%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20OB%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20SW%20stroke-dasharray%3A%205%205%0A"}),e[2]||(e[2]=t('<p><code>ctx.edit()</code> takes the same path with <code>edit</code> on the hook payload. The live previews of <code>ctx.stream()</code> (drafts and in-place edits) run only the <code>before(&#39;send&#39;)</code> hooks; the messages a stream finally sends take the full path. <code>bot.enqueue()</code> (durability only) runs the <code>before(&#39;send&#39;)</code> hooks, journals the send and returns at once; the outbox sweeper delivers it.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2>',2)),d(o,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20start%5B%22start()%22%5D%0A%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20A1%5B%22storage%22%5D%20--%3E%20A2%5B%22coordination%22%5D%20--%3E%20A3%5B%22restore%20conversations%20%2B%20handoffs%22%5D%20--%3E%20A4%5B%22durability%3A%20recover%22%5D%20--%3E%20A5%5B%22transport%22%5D%20--%3E%20A6%5B%22jobs%20(scheduler)%22%5D%0A%20%20%20%20end%0A%20%20%20%20style%20A2%20stroke-dasharray%3A%205%205%0A%20%20%20%20style%20A4%20stroke-dasharray%3A%205%205%0A"}),e[3]||(e[3]=t('<p><code>stop()</code> closes inbound and cancels broadcasts, emits <code>&#39;stopping&#39;</code> (plugins cancel long work there, e.g. <code>@botmesh/ai</code> aborts its model calls), stops or pauses the steps that produce new work (scheduler, durability sweeper), optionally drains in-flight sends (<code>stop({ drain: true })</code>), closes paced sends and aborts conversations (checkpoints are kept), then stops the remaining steps in reverse order (the <code>storage</code> step first lets sends still in flight and the ledger rows of sends the provider already accepted land, up to 5 s, before it closes the store). If <code>start()</code> fails, the steps already started are rolled back in reverse order and the error is rethrown.</p><p>An opt-in feature adds a <strong>lifecycle step</strong>; it does not scatter <code>if</code>s through the start and stop code.</p><h2 id="where-the-opt-ins-plug-in" tabindex="-1">Where the opt-ins plug in <a class="header-anchor" href="#where-the-opt-ins-plug-in" aria-label="Permalink to &quot;Where the opt-ins plug in&quot;">​</a></h2><p>All of them are off by default. A bot that does not configure them runs exactly the code path described above without the dashed boxes.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Config</th><th>Stages it touches</th><th>Guide</th></tr></thead><tbody><tr><td>Durable processing</td><td><code>durability</code></td><td>Inbound: journals each event in an <strong>inbox</strong> before dispatch and acknowledges it once the work it started settled; replays it after a crash. Outbound: idempotency lookup and an <strong>outbox</strong> journal per send, with retries and a dead-letter queue. Lifecycle: a <code>durability</code> step</td><td><a href="/botmesh/guide/durability">Durable processing</a></td></tr><tr><td>Multi-replica coordination</td><td><code>coordination</code></td><td>Inbound: each chat is processed under a cross-replica <strong>turn</strong>, in ingress order. Outbound: a <strong>fence</strong> refuses sends from a replica that lost its turn or the provider session. Lifecycle: a <code>coordination</code> step and leader election for exclusive transports. With <code>coordination.handover</code>, flow checkpoints carry the cut-short answer and non-persistent flows can be forwarded</td><td><a href="/botmesh/guide/replicas">Running N replicas</a></td></tr><tr><td>Durable scheduler</td><td><code>scheduler</code></td><td>Jobs: tasks with an <code>id</code> are stored, survive restarts with a missed-run policy and run on one replica per occurrence (a <strong>lease</strong>)</td><td><a href="/botmesh/guide/scheduler">Scheduler</a></td></tr><tr><td>Tracing</td><td><code>telemetry</code></td><td>Wraps the stages it observes in spans without changing their order or timing: provider event (<code>bot.inbound</code>), persistence, dispatch, handler, each conversation turn between waits, pacing and every send; <code>@botmesh/ai</code> adds model and tool spans. <code>@botmesh/otel</code> (outside the core, <code>@opentelemetry/api</code> as an optional peer) exports them. Each scheduled task run is a root <code>bot.task</code> span, and a conversation resumed on another replica (or after a restart) links its first turn to the turn that wrote the checkpoint (<code>FlowCheckpoint.trace</code>, W3C)</td><td><a href="/botmesh/guide/tracing">Tracing</a></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/botmesh/guide/concepts">Core concepts</a>: the full routing order and conversations.</li><li><a href="/botmesh/guide/hooks">Hooks</a>: the <code>message</code> and <code>send</code> hook contracts.</li><li><a href="/botmesh/guide/plugins">Plugins</a>: what a plugin-scoped bot tracks and undoes.</li></ul>',7))])}const f=r(n,[["render",i]]);export{m as __pageData,f as default};
